package com.slss.domain;
import jakarta.persistence.*;
@Entity @Table(name="production_import_failures")
public class ProductionImportFailure { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="job_id",nullable=false) ProductionImportJob job; @Column(name="row_number") int rowNumber; @Column(name="machine_sn") String machineSn; @Column(name="error_message",nullable=false) String errorMessage; @Column(name="error_category") String errorCategory; @Column(name="raw_data",columnDefinition="TEXT") String rawData; public Long getId(){return id;} public int getRowNumber(){return rowNumber;} public String getMachineSn(){return machineSn;} public String getErrorMessage(){return errorMessage;} public String getErrorCategory(){return errorCategory;} public String getRawData(){return rawData;} public void setJob(ProductionImportJob v){job=v;} public void setRowNumber(int v){rowNumber=v;} public void setMachineSn(String v){machineSn=v;} public void setErrorMessage(String v){errorMessage=v;} public void setErrorCategory(String v){errorCategory=v;} public void setRawData(String v){rawData=v;} }
